// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import {orientLayoutGroups} from '../../../main/frontend/graph-explorer/graph-layout-group-centers.ts';

function fixture() {
  return {nodes: [{id: 'a', label: 'A', kind: 'iri', x: -80, y: 0}, {id: 'b', label: 'B', kind: 'iri', x: 80, y: 0},
    {id: 'outside', label: 'Outside', kind: 'iri', x: 500, y: 0}],
    edges: [{id: 'e', source: 'a', target: 'outside', predicate: 'urn:p', label: 'p'}], revision: 1};
}

test('group orientation brings boundary members towards their neighbors without distorting the interior', () => {
  const graph = fixture(), before = structuredClone(graph);
  const positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  orientLayoutGroups(graph, [[0, 1], [2]], positions, new Map([['0', {x: 0, y: 0}], ['1', {x: 500, y: 0}]]));
  assert.ok(positions.get('a').x > 0, 'boundary member should face its external neighbor');
  assert.equal(Math.abs(positions.get('a').x - positions.get('b').x), 160);
  assert.deepEqual(positions.get('outside'), {x: 500, y: 0});
  assert.deepEqual(graph, before);
});

test('extending, repairing and pinned groups never reflect an existing mental map', () => {
  for (const options of [{incremental: true}, {repairOnly: true}, {localNodeIds: new Set(['a', 'b'])}, {}]) {
    const graph = fixture();
    if (!Object.keys(options).length) graph.nodes[0].pinned = true;
    const positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}])), before = structuredClone(positions);
    orientLayoutGroups(graph, [[0, 1], [2]], positions, new Map([['0', {x: 0, y: 0}], ['1', {x: 500, y: 0}]]), options);
    assert.deepEqual(positions, before);
  }
});
